// Narrower enum covering only the four terminal delivery
// outcomes returned to a synchronous `wait: true` send.
// On the SendMailResult shape, `delivery_status` is always
// equal to `status` whenever both are present (i.e. on
// terminal-state replays and live wait=true responses).
// The two fields exist so callers that want to type-narrow
// on "this is a delivery outcome" can pattern-match against
// the four-value enum without handling the broader
// SentEmailStatus value set (which also covers `queued`,
// `submitted_to_agent`, `agent_failed`, `gate_denied`,
// `unknown`).
// On async-mode and pre-terminal responses, `delivery_status`
// is absent and only `status` is populated. Use `status` if
// you want a single field that's always present.
// Ref: #/components/schemas/DeliveryStatus
type DeliveryStatus string

const (
	DeliveryStatusDelivered   DeliveryStatus = "delivered"
	DeliveryStatusBounced     DeliveryStatus = "bounced"
	DeliveryStatusDeferred    DeliveryStatus = "deferred"
	DeliveryStatusWaitTimeout DeliveryStatus = "wait_timeout"
)

// AllValues returns all DeliveryStatus values.
func (DeliveryStatus) AllValues() []DeliveryStatus {
	return []DeliveryStatus{
		DeliveryStatusDelivered,
		DeliveryStatusBounced,
		DeliveryStatusDeferred,
		DeliveryStatusWaitTimeout,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s DeliveryStatus) MarshalText() ([]byte, error) {
	switch s {
	case DeliveryStatusDelivered:
		return []byte(s), nil
	case DeliveryStatusBounced:
		return []byte(s), nil
	case DeliveryStatusDeferred:
		return []byte(s), nil
	case DeliveryStatusWaitTimeout:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *DeliveryStatus) UnmarshalText(data []byte) error {
	switch DeliveryStatus(data) {
	case DeliveryStatusDelivered:
		*s = DeliveryStatusDelivered
		return nil
	case DeliveryStatusBounced:
		*s = DeliveryStatusBounced
		return nil
	case DeliveryStatusDeferred:
		*s = DeliveryStatusDeferred
		return nil
	case DeliveryStatusWaitTimeout:
		*s = DeliveryStatusWaitTimeout
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

