// Possible values for DomainType.
const (
	VerifiedDomainDomain   DomainType = "VerifiedDomain"
	UnverifiedDomainDomain DomainType = "UnverifiedDomain"
)

// IsVerifiedDomain reports whether Domain is VerifiedDomain.
